import json
Ra, Rb, Nx = [], [], []
fr = -1
def ins(a, b):
    global fr
    Ra.append(a); Rb.append(b); Nx.append(fr); fr = len(Ra) - 1
def walk(a):
    prev, r = -1, fr
    while r >= 0 and Ra[r] != a:
        prev, r = r, Nx[r]
    return r, prev
def get(a):
    r, _ = walk(a)
    return Rb[r] if r >= 0 else -1
def delete(a):
    global fr
    r, prev = walk(a)
    if r >= 0:
        if prev < 0:
            fr = Nx[r]
        else:
            Nx[prev] = Nx[r]
for a, b in [(1, 50), (2, 51), (1, 52)]:
    ins(a, b)
first = get(1)
delete(1)
print(json.dumps({"get1": first, "get1_after": get(1), "get2": get(2), "front": fr}))
